descriptor.controllerScript:
self.onInit = function () {
  // ✅ TailwindCSS injection (one-time)
  if (!document.getElementById('tailwindcss')) {
    const script = document.createElement('script');
    script.src = 'https://cdn.tailwindcss.com';
    script.id = 'tailwindcss';
    script.onload = () => self.ctx.detectChanges();
    document.head.appendChild(script);
  }

  // ✅ Init vars
  self.cpu_usage = 'N/A';
  self.cpu_usage_ts = '';
  self.device_temperature = 'N/A';
  self.device_temperature_ts = '';

  console.log('🟢 Widget initialized');
};

self.onDataUpdated = function () {
  console.log('📡 onDataUpdated() triggered');
  console.log('📦 ctx.data snapshot:', self.ctx.data);

  // ✅ CPU usage
  const cpu = self.ctx.data.find(d => d.dataKey.name === 'cpu_usage');
  if (cpu && cpu.data.length) {
    const [ts, val] = cpu.data.at(-1);
    const percent = parseFloat(val) * 100;
    self.cpu_usage = percent.toFixed(2);
    self.cpu_usage_ts = new Date(ts).toLocaleTimeString();

    console.log(`🧠 CPU Usage: raw=${val}, percent=${self.cpu_usage}% at ${self.cpu_usage_ts}`);
  } else {
    console.warn('⚠️ No cpu_usage data found');
  }

  // ✅ Device temperature
  const temp = self.ctx.data.find(d => d.dataKey.name === 'device_temperature');
  if (temp && temp.data.length) {
    const [ts, val] = temp.data.at(-1);
    self.device_temperature = parseFloat(val).toFixed(2);
    self.device_temperature_ts = new Date(ts).toLocaleTimeString();

    console.log(`🔥 Temp: raw=${val}, °C=${self.device_temperature} at ${self.device_temperature_ts}`);
  } else {
    console.warn('⚠️ No device_temperature data found');
  }

  self.ctx.detectChanges();
};

self.onDestroy = function () {
  console.log('🧹 Widget destroyed');
};

